// KocHivoire — le site complet dans un seul fichier.
// Lancer : node server.js   (Node.js 18 ou plus, aucune installation nécessaire)
// Réglages (variables d'environnement) : ADMIN_PASSWORD, WAVE_API_KEY, WAVE_WEBHOOK_SECRET, SITE_URL, DATA_DIR
// Sans WAVE_API_KEY, le site tourne en MODE TEST (paiements simulés).
const mini = (() => {
// Mini serveur web sans dépendance (remplace express et dotenv).
// Seules les fonctions utilisées par server.js sont fournies.
const http = require('http');
const fs = require('fs');
const path = require('path');

function loadEnv(file) {
  try {
    for (const line of fs.readFileSync(file, 'utf8').split(/\r?\n/)) {
      const m = /^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/.exec(line);
      if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2].replace(/^["']|["']$/g, '');
    }
  } catch { /* pas de fichier .env : on utilise les variables de l'hébergeur */ }
}

const TYPES = {
  '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8', '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg',
  '.webp': 'image/webp', '.svg': 'image/svg+xml', '.ico': 'image/x-icon', '.txt': 'text/plain; charset=utf-8',
};

function readBody(req, limit) {
  return new Promise((resolve, reject) => {
    const chunks = []; let size = 0;
    req.on('data', (c) => { size += c.length; if (size > limit) { reject(Object.assign(new Error('Trop volumineux'), { status: 413 })); req.destroy(); } else chunks.push(c); });
    req.on('end', () => resolve(Buffer.concat(chunks)));
    req.on('error', reject);
  });
}

function json({ limit = '1mb' } = {}) {
  const max = parseInt(limit, 10) * 1024 * 1024;
  return async (req, res, next) => {
    if (req.body !== undefined || !['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) return next();
    if (!/json/i.test(req.headers['content-type'] || '')) { req.body = {}; return next(); }
    try {
      const buf = await readBody(req, max);
      req.body = buf.length ? JSON.parse(buf.toString('utf8')) : {};
      next();
    } catch (e) { res.status(e.status || 400).json({ error: e.status === 413 ? 'Envoi trop volumineux.' : 'Données invalides.' }); }
  };
}
function raw() {
  return async (req, res, next) => {
    try { req.body = await readBody(req, 1024 * 1024); next(); } catch { res.sendStatus(400); }
  };
}
function serveStatic(root, { maxAge } = {}) {
  root = path.resolve(root);
  return (req, res, next) => {
    if (req.method !== 'GET' && req.method !== 'HEAD') return next();
    let rel; try { rel = decodeURIComponent(req.path); } catch { return next(); }
    if (rel.endsWith('/')) rel += 'index.html';
    const file = path.resolve(path.join(root, rel));
    if (!file.startsWith(root + path.sep)) return next();
    fs.stat(file, (err, st) => {
      if (err || !st.isFile()) return next();
      const h = { 'Content-Type': TYPES[path.extname(file).toLowerCase()] || 'application/octet-stream', 'Content-Length': st.size };
      if (maxAge) h['Cache-Control'] = 'public, max-age=' + (parseInt(maxAge, 10) * 86400);
      res.writeHead(200, h);
      if (req.method === 'HEAD') return res.end();
      fs.createReadStream(file).pipe(res);
    });
  };
}

function compile(pattern) {
  const keys = [];
  const re = new RegExp('^' + pattern.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/\/:(\w+)/g, (_, k) => { keys.push(k); return '/([^/]+)'; }) + '/?$');
  return { re, keys };
}

function createApp() {
  const stack = []; // { method, prefix?, matcher?, handlers }
  const add = (method, p, handlers) => stack.push({ method, ...compile(p), handlers });
  const app = {
    use(a, ...rest) {
      if (typeof a === 'string') stack.push({ method: '*', prefix: a.replace(/\/$/, ''), handlers: rest });
      else stack.push({ method: '*', prefix: '', handlers: [a, ...rest] });
    },
    get: (p, ...h) => add('GET', p, h), post: (p, ...h) => add('POST', p, h),
    put: (p, ...h) => add('PUT', p, h), delete: (p, ...h) => add('DELETE', p, h),
    listen(port, cb) { return http.createServer(handle).listen(port, cb); },
  };

  function handle(req, res) {
    const u = new URL(req.url, 'http://local');
    req.path = u.pathname; req.query = Object.fromEntries(u.searchParams);
    req.ip = (req.headers['x-forwarded-for'] || '').split(',')[0].trim() || req.socket.remoteAddress;
    req.get = (h) => req.headers[h.toLowerCase()];
    res.status = (c) => { res.statusCode = c; return res; };
    res.json = (o) => { if (!res.headersSent) res.setHeader('Content-Type', 'application/json; charset=utf-8'); res.end(JSON.stringify(o)); };
    res.sendStatus = (c) => { res.statusCode = c; res.end(); };

    let i = 0;
    const next = () => {
      while (i < stack.length) {
        const l = stack[i++];
        if (l.method !== '*' && l.method !== req.method && !(l.method === 'GET' && req.method === 'HEAD')) continue;
        let m;
        if (l.prefix !== undefined) {
          if (l.prefix && !(req.path === l.prefix || req.path.startsWith(l.prefix + '/'))) continue;
          const saved = req.path; const sub = l.prefix ? req.path.slice(l.prefix.length) || '/' : req.path;
          return runChain(l.handlers, () => { req.path = saved; next(); }, sub, saved);
        }
        if (!(m = l.re.exec(req.path))) continue;
        req.params = {}; l.keys.forEach((k, j) => { req.params[k] = decodeURIComponent(m[j + 1]); });
        return runChain(l.handlers, next);
      }
      res.statusCode = 404; res.setHeader('Content-Type', 'text/plain; charset=utf-8'); res.end('Page introuvable');
    };
    const runChain = (hs, done, sub, saved) => {
      let k = 0;
      const step = () => {
        if (k >= hs.length) return done();
        const h = hs[k++];
        if (sub !== undefined) req.path = sub;
        try {
          const r = h(req, res, () => { if (saved !== undefined) req.path = saved; step(); });
          if (r && r.catch) r.catch(fail);
        } catch (e) { fail(e); }
      };
      step();
    };
    const fail = (e) => { console.error(e); if (!res.headersSent) res.status(500).json({ error: 'Erreur serveur.' }); else res.end(); };
    next();
  }
  return app;
}

return { createApp, json, raw, static: serveStatic, loadEnv };

})();
