// ---------- Commande depuis le panier : le serveur recalcule le prix ----------
app.post('/api/checkout', async (req, res) => {
  const { items, ship, client } = req.body || {};
  if (!['air', 'sea'].includes(ship) || !Array.isArray(items) || !items.length)
    return res.status(400).json({ error: 'Panier invalide.' });
  if (!client || !client.nom || !client.tel)
    return res.status(400).json({ error: 'Indique ton nom et ton numéro WhatsApp.' });

  const products = publicProducts().map((p) => ({ ...p, promoFin: '' }));
  let total = 0, kg = 0, cbm = 0; const lines = [];
  for (const it of items) {
    const p = products.find((x) => x.id === Number(it.id));
    const qty = Math.floor(Number(it.qty));
    const kind = it.kind === 'gros' ? 'gros' : 'detail';
    if (!p || !(qty > 0) || (kind === 'gros' && qty < p.min))
      return res.status(400).json({ error: 'Un article du panier est invalide.' });
    const u = round25(unitPrice(p, kind));
    total += u * qty; kg += p.w * qty; cbm += p.v * qty;
    lines.push({ id: p.id, n: p.n, kind, qty, unit: u });
  }
  const transport = round25(shipCost(kg, cbm, ship));
  lines.push({ n: ship === 'air' ? `Transport avion (${kg.toFixed(2)} kg)` : `Transport bateau (${cbm.toFixed(3)} CBM)`, qty: 1, unit: transport });
  total += transport;
  const ref = newRef();
  try {
    const s = await createWaveSession(total, ref);
    const orders = loadOrders();
    orders[ref] = { ref, lines, ship, total, client, status: 'en attente', waveSessionId: s.id,
      createdAt: new Date().toISOString(), arrivalDays: DAYS[ship] };
    saveOrders(orders);
    bump('commandes');
    emit('order', { ref, total, client: client.nom, ville: client.ville || '', ship });
    res.json({ ref, url: s.wave_launch_url });
  } catch (e) {
    console.error(e);
    res.status(502).json({ error: 'Wave ne répond pas pour le moment. Réessaie dans un instant.' });
  }
});

