// ---------- Admin : produits, nouveautés, réductions ----------
const ICONS = ['phone', 'audio', 'shirt', 'shoe', 'home', 'bag', 'hair', 'beauty', 'pot'];
function cleanProduct(b, old = {}) {
  const num = (v, d) => (v === undefined || v === '' ? d : Number(v));
  const p = {
    ...old,
    n: String(b.n ?? old.n ?? '').trim().slice(0, 120),
    cat: String(b.cat ?? old.cat ?? '').trim().slice(0, 40),
    desc: String(b.desc ?? old.desc ?? '').trim().slice(0, 600),
    c: num(b.c, old.c), w: num(b.w, old.w), v: num(b.v, old.v), min: Math.floor(num(b.min, old.min ?? 10)),
    i: ICONS.includes(b.i) ? b.i : (old.i || 'bag'),
    img: String(b.img ?? old.img ?? ''),
    nouveau: b.nouveau !== undefined ? !!b.nouveau : !!old.nouveau,
    actif: b.actif !== undefined ? !!b.actif : old.actif !== false,
    promo: Math.min(90, Math.max(0, Math.round(num(b.promo, old.promo ?? 0)))),
    promoFin: /^\d{4}-\d{2}-\d{2}$/.test(b.promoFin ?? '') ? b.promoFin : (b.promoFin === '' ? '' : old.promoFin || ''),
  };
  if (!p.n) throw new Error('Le nom du produit est obligatoire.');
  if (!p.cat) throw new Error('Choisis une catégorie.');
  for (const k of ['c', 'w', 'v']) if (!(p[k] >= 0)) throw new Error('Coût, poids et volume doivent être des nombres positifs.');
  if (!(p.c > 0)) throw new Error("Indique le coût d'achat en Chine.");
  if (!(p.min >= 1)) throw new Error('Le minimum en gros doit être au moins 1.');
  if (!p.nouveau) delete p.nouveauDepuis; else if (!old.nouveau) p.nouveauDepuis = new Date().toISOString();
  return p;
}
app.get('/api/admin/products', admin, (req, res) => res.json(loadProducts()));
app.post('/api/admin/products', admin, (req, res) => {
  try {
    const list = loadProducts();
    const p = cleanProduct(req.body);
    p.id = list.reduce((m, x) => Math.max(m, x.id), 0) + 1;
    list.unshift(p); saveProducts(list); res.json(p);
  } catch (e) { res.status(400).json({ error: e.message }); }
});
app.put('/api/admin/products/:id', admin, (req, res) => {
  try {
    const list = loadProducts(); const i = list.findIndex((x) => x.id === Number(req.params.id));
    if (i < 0) return res.sendStatus(404);
    list[i] = cleanProduct(req.body, list[i]); saveProducts(list); res.json(list[i]);
  } catch (e) { res.status(400).json({ error: e.message }); }
});
app.delete('/api/admin/products/:id', admin, (req, res) => {
  const list = loadProducts().filter((x) => x.id !== Number(req.params.id));
  saveProducts(list); res.json({ ok: true });
});
// Réduction groupée sur une catégorie (ou tout le catalogue)
app.post('/api/admin/promo', admin, (req, res) => {
  const promo = Math.min(90, Math.max(0, Math.round(Number(req.body.promo) || 0)));
  const fin = /^\d{4}-\d{2}-\d{2}$/.test(req.body.promoFin || '') ? req.body.promoFin : '';
  const list = loadProducts(); let n = 0;
  for (const p of list) if (!req.body.cat || p.cat === req.body.cat) { p.promo = promo; p.promoFin = fin; n++; }
  saveProducts(list); res.json({ updated: n });
});
// Photo produit : image envoyée en base64 (data URL), enregistrée dans DATA_DIR/uploads
app.post('/api/admin/upload', admin, (req, res) => {
  const m = /^data:image\/(jpeg|png|webp);base64,(.+)$/.exec(req.body.data || '');
  if (!m) return res.status(400).json({ error: 'Envoie une photo JPG, PNG ou WebP.' });
  const buf = Buffer.from(m[2], 'base64');
  if (buf.length > 5 * 1024 * 1024) return res.status(400).json({ error: 'Photo trop lourde (5 Mo maximum).' });
  const name = crypto.randomBytes(8).toString('hex') + '.' + (m[1] === 'jpeg' ? 'jpg' : m[1]);
  fs.writeFileSync(path.join(UPLOADS_DIR, name), buf);
  res.json({ url: '/uploads/' + name });
});

// ---------- Flux en direct : boutique et admin ----------
app.get('/api/stream', (req, res) => { openStream(req, res, shopClients); pushOnline(); });
const lastHit = new Map();
setInterval(() => lastHit.clear(), 600000);
app.post('/api/track', (req, res) => {
  const now = Date.now(), key = req.ip + (req.body?.type || '');
  if (now - (lastHit.get(key) || 0) < 400) return res.sendStatus(204);
  lastHit.set(key, now);
  const { type, id } = req.body || {};
  if (type === 'visit') { bump('visites'); emit('visit'); }
  else if (type === 'add') {
    const p = loadProducts().find((x) => x.id === Number(id));
    if (p) { bump('ajouts'); emit('add', { product: p.n, kind: req.body.kind === 'gros' ? 'gros' : 'détail', qty: Math.min(10000, Math.max(1, Number(req.body.qty) || 1)) }); }
  }
  res.sendStatus(204);
});
app.post('/api/admin/token', admin, (req, res) => {
  const t = crypto.randomBytes(16).toString('hex');
  adminTokens.set(t, Date.now() + 12 * 3600e3);
  res.json({ token: t });
});
app.get('/api/admin/live', (req, res) => {
  const exp = adminTokens.get(String(req.query.token || ''));
  if (!exp || exp < Date.now()) return res.sendStatus(401);
  openStream(req, res, adminClients);
  sse(res, 'init', { online: shopClients.size, today: stats[dayKey()] || zeroDay(), recent: recent.slice(0, 60) });
});

app.listen(PORT, () => console.log(`KocHivoire en ligne sur le port ${PORT}`));
